<path v-for="room in roomsMap"
      :key="room.name"
      :d="room.pathData"
      fill="red"
      :fill-opacity="room.fillOpacity"
      :class="{ 'active-room': room.isActive }"
      @mouseenter="toggleActive(room.name)"
      @mousemove="updateMouseLocation"
      @mouseleave="toggleActiveToNull"
      @click="handleDataSelection(room.name)"
/>
<text v-for="room in roomsMap"
      class="room-name"
      opacity="1"
      :x="room.textx"
      :y="room.texty"
      :dy="-55"
>
  {{room.name}}
</text>
<text v-for="room in roomsMap"
      class="room-value"
      :x="room.textx"
      :y="room.texty"
      :dx="25"
>
  {{room.value}} 件
</text>
<text v-for="room in roomsMap"
      class="fire-emoji"
      :x="room.textx"
      :y="room.texty"
      :dx="-25"
>
  🔥
</text>


